import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices } from '../src/reports.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty array for empty invoices list', () => {
  const r = overdueInvoices([], '2026-10-10');
  assert.deepEqual(r, []);
});

test('overdueInvoices excludes draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const r = overdueInvoices([invoice], '2026-10-15');
  assert.deepEqual(r, []);
});

test('overdueInvoices excludes paid invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const paid = recordPayment(issued, { amount: 10285, date: '2026-10-08' }).value;

  const r = overdueInvoices([paid], '2026-10-15');
  assert.deepEqual(r, []);
});

test('overdueInvoices excludes invoices not yet due', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // NET30 from 2026-10-07 = due 2026-11-06

  const r = overdueInvoices([issued], '2026-11-05');
  assert.deepEqual(r, []);
});

test('overdueInvoices includes invoices with dueDate before asOf', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // NET14 from 2026-10-07 = due 2026-10-21
  const r = overdueInvoices([issued], '2026-10-22');

  assert.equal(r.length, 1);
  assert.equal(r[0].number, 'INV-2026-0001');
  assert.equal(r[0].daysOverdue, 1);
});

test('overdueInvoices excludes invoices due on asOf date', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // NET14 from 2026-10-07 = due 2026-10-21
  const r = overdueInvoices([issued], '2026-10-21');

  assert.deepEqual(r, []);
});

test('overdueInvoices includes partially paid overdue invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // NET14 from 2026-10-01 = due 2026-10-15, total 10285
  const partial = recordPayment(issued, { amount: 5000, date: '2026-10-08' }).value;

  const r = overdueInvoices([partial], '2026-10-20');

  assert.equal(r.length, 1);
  assert.equal(r[0].number, 'INV-2026-0001');
  assert.equal(r[0].daysOverdue, 5);
  assert.equal(r[0].due, 5285);
});

test('overdueInvoices returns correct structure', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const r = overdueInvoices([issued], '2026-10-20');

  assert.equal(r.length, 1);
  const inv = r[0];
  assert.ok(inv.number);
  assert.ok(inv.customerId);
  assert.ok(inv.dueDate);
  assert.equal(typeof inv.daysOverdue, 'number');
  assert.equal(typeof inv.due, 'number');
  assert.equal(Object.keys(inv).length, 5);
});

test('overdueInvoices sorts by daysOverdue descending', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;
  const issued3 = issueInvoice(inv3, ['INV-2026-0001', 'INV-2026-0002']).value;

  // NET30: inv1 due 2026-11-09, inv2 due 2026-10-31, inv3 due 2026-11-04
  const r = overdueInvoices([issued1, issued2, issued3], '2026-11-15');

  assert.equal(r.length, 3);
  // inv1 has most days overdue
  assert.equal(r[0].number, 'INV-2026-0001');
  assert.equal(r[0].daysOverdue, 6); // 2026-11-15 - 2026-11-09
  // inv3 is second
  assert.equal(r[1].number, 'INV-2026-0003');
  assert.equal(r[1].daysOverdue, 11); // 2026-11-15 - 2026-11-04
  // inv2 is third (least overdue)
  assert.equal(r[2].number, 'INV-2026-0002');
  assert.equal(r[2].daysOverdue, 15); // 2026-11-15 - 2026-10-31
});

test('overdueInvoices with single overdue invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // NET30 from 2026-10-01 = due 2026-10-31, C-002 standard tier total 20570
  const r = overdueInvoices([issued], '2026-11-10');

  assert.equal(r.length, 1);
  assert.equal(r[0].number, 'INV-2026-0001');
  assert.equal(r[0].customerId, 'C-002');
  assert.equal(r[0].dueDate, '2026-10-31');
  assert.equal(r[0].daysOverdue, 10);
  assert.equal(r[0].due, 20570);
});

test('overdueInvoices with multiple overdue invoices same customer', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const r = overdueInvoices([issued1, issued2], '2026-11-15');

  assert.equal(r.length, 2);
  assert.equal(r[0].customerId, 'C-001');
  assert.equal(r[1].customerId, 'C-001');
});

test('overdueInvoices with multiple overdue invoices different customers', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const r = overdueInvoices([issued1, issued2], '2026-11-15');

  assert.equal(r.length, 2);
  assert.equal(r[0].customerId, 'C-001');
  assert.equal(r[1].customerId, 'C-002');
});

test('overdueInvoices mix of overdue and not overdue', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-11-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  // inv1 due 2026-10-31, inv2 due 2026-12-01
  const r = overdueInvoices([issued1, issued2], '2026-11-15');

  assert.equal(r.length, 1);
  assert.equal(r[0].number, 'INV-2026-0001');
});

test('overdueInvoices with zero daysOverdue', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // NET30 from 2026-10-07 = due 2026-11-06
  const r = overdueInvoices([issued], '2026-11-07');

  assert.equal(r.length, 1);
  assert.equal(r[0].daysOverdue, 1);
});

test('overdueInvoices with large daysOverdue', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // NET30 from 2026-01-01 = due 2026-01-31
  const r = overdueInvoices([issued], '2026-10-07');

  assert.equal(r.length, 1);
  assert.equal(r[0].daysOverdue, 250); // Approximately 250 days
});

test('overdueInvoices with year boundaries', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // NET30 from 2025-12-15 = due 2026-01-14
  const r = overdueInvoices([issued], '2026-02-01');

  assert.equal(r.length, 1);
  assert.equal(r[0].daysOverdue, 18);
});

test('overdueInvoices calculates due correctly for fully unpaid invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // C-002 standard tier: 8500 + 1785 = 10285
  const r = overdueInvoices([issued], '2026-11-15');

  assert.equal(r.length, 1);
  assert.equal(r[0].due, 10285);
});

test('overdueInvoices calculates due correctly for partially paid invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // C-001 gold tier: 8500 - 425 + 1703 = 9778
  const partial = recordPayment(issued, { amount: 5000, date: '2026-10-05' }).value;

  const r = overdueInvoices([partial], '2026-11-15');

  assert.equal(r.length, 1);
  assert.equal(r[0].due, 4778);
});

test('overdueInvoices with EOM terms', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // EOM from 2026-10-15 = due 2026-10-31
  const r = overdueInvoices([issued], '2026-11-10');

  assert.equal(r.length, 1);
  assert.equal(r[0].daysOverdue, 10);
});

test('overdueInvoices filters by status correctly', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;

  const r = overdueInvoices([draft, issued], '2026-11-15');

  assert.equal(r.length, 1);
  assert.equal(r[0].number, 'INV-2026-0001');
});

test('overdueInvoices with null invoice skipped', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;

  const r = overdueInvoices([null, issued, undefined], '2026-11-15');

  assert.equal(r.length, 1);
  assert.equal(r[0].number, 'INV-2026-0001');
});

test('overdueInvoices with discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // 17000 - 1700 + 3213 = 18513
  const r = overdueInvoices([issued], '2026-11-15');

  assert.equal(r.length, 1);
  assert.equal(r[0].due, 18513);
});

test('overdueInvoices with large number of invoices', () => {
  const invoices = [];

  for (let i = 1; i <= 20; i++) {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: `2026-${String(i).padStart(2, '0')}-01`,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const issued = issueInvoice(invoice, invoices.map(inv => inv.number)).value;
    invoices.push(issued);
  }

  const r = overdueInvoices(invoices, '2026-12-15');

  // All invoices with due date before 2026-12-15 should be included
  assert.ok(r.length > 0);
  // Should be sorted by daysOverdue descending
  for (let i = 1; i < r.length; i++) {
    assert.ok(r[i - 1].daysOverdue >= r[i].daysOverdue);
  }
});

test('overdueInvoices multiple payments on single invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // C-001 gold tier: 42500 - 2125 (5% discount) + 8493.75 -> 48868.75 (banker's rounding applied)
  const p1 = recordPayment(issued, { amount: 10000, date: '2026-10-05' }).value;
  const p2 = recordPayment(p1, { amount: 10000, date: '2026-10-10' }).value;
  const p3 = recordPayment(p2, { amount: 5000, date: '2026-10-15' }).value;

  const r = overdueInvoices([p3], '2026-11-15');

  assert.equal(r.length, 1);
  const totalPaid = 10000 + 10000 + 5000;
  const totalDue = 42500 - 2125 + 8868; // VAT is 8867.75 rounded to 8868
  assert.equal(r[0].due, totalDue - totalPaid);
});

test('overdueInvoices with early dates (all not yet due)', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // NET30 from 2026-10-01 = due 2026-10-31
  const r = overdueInvoices([issued], '2026-10-30');

  assert.deepEqual(r, []);
});

test('overdueInvoices with very early asOf date', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;

  const r = overdueInvoices([issued], '2026-10-08');

  assert.deepEqual(r, []);
});

test('overdueInvoices preserves customer ID', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;

  const r = overdueInvoices([issued], '2026-11-15');

  assert.equal(r.length, 1);
  assert.equal(r[0].customerId, 'C-003');
});

test('overdueInvoices preserves invoice number and dueDate', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(invoice, []).value;

  const r = overdueInvoices([issued], '2026-11-01');

  assert.equal(r.length, 1);
  assert.equal(r[0].number, 'INV-2026-0001');
  assert.equal(r[0].dueDate, '2026-10-29');
});

test('overdueInvoices with multiple invoices same due date', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  // Both have NET30 from 2026-09-30 = due 2026-10-30
  const r = overdueInvoices([issued1, issued2], '2026-11-15');

  assert.equal(r.length, 2);
  assert.equal(r[0].daysOverdue, 16);
  assert.equal(r[1].daysOverdue, 16);
});

test('overdueInvoices handles stable sort for same daysOverdue', () => {
  const invoices = [];

  for (let i = 0; i < 3; i++) {
    const invoice = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-09-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value;

    const issued = issueInvoice(invoice, invoices.map(inv => inv.number)).value;
    invoices.push(issued);
  }

  // All should have same dueDate and daysOverdue
  const r = overdueInvoices(invoices, '2026-11-15');

  assert.equal(r.length, 3);
  assert.equal(r[0].daysOverdue, 16);
  assert.equal(r[1].daysOverdue, 16);
  assert.equal(r[2].daysOverdue, 16);
});

test('overdueInvoices does not mutate input', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const invoicesCopy = JSON.parse(JSON.stringify([issued]));

  overdueInvoices([issued], '2026-11-15');

  assert.deepEqual([issued], invoicesCopy);
});

