test('overdueInvoices multiple payments on single invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // C-001 gold tier: 42500 - 2125 (5% discount) + 8493.75 -> 48868.75 (banker's rounding applied)
  const p1 = recordPayment(issued, { amount: 10000, date: '2026-10-05' }).value;
  const p2 = recordPayment(p1, { amount: 10000, date: '2026-10-10' }).value;
  const p3 = recordPayment(p2, { amount: 5000, date: '2026-10-15' }).value;

  const r = overdueInvoices([p3], '2026-11-15');

  assert.equal(r.length, 1);
  const totalPaid = 10000 + 10000 + 5000;
  const totalDue = 42500 - 2125 + 8868; // VAT is 8867.75 rounded to 8868
  assert.equal(r[0].due, totalDue - totalPaid);
});

