  }).value;

  const issued = issueInvoice(invoice, []).value;
  const invoicesCopy = JSON.parse(JSON.stringify([issued]));

  overdueInvoices([issued], '2026-11-15');

  assert.deepEqual([issued], invoicesCopy);
});

